actions.script:
import java.time.LocalDate
import java.time.temporal.TemporalAdjusters

def refDate = referenceDate instanceof java.sql.Date ?
    ((java.sql.Date) referenceDate).toLocalDate() :
    (referenceDate instanceof java.util.Date ?
        new java.sql.Date(referenceDate.time).toLocalDate() :
        LocalDate.now())

def year = refDate.year
def startMonth = fiscalYearStartMonth as int

LocalDate fyStart
if (startMonth == 1) {
    fyStart = LocalDate.of(year, 1, 1)
} else if (refDate.monthValue >= startMonth) {
    fyStart = LocalDate.of(year, startMonth, 1)
} else {
    fyStart = LocalDate.of(year - 1, startMonth, 1)
}

def fyEnd = fyStart.plusYears(1).minusDays(1)

context.fyStartDate = java.sql.Date.valueOf(fyStart)
context.fyEndDate = java.sql.Date.valueOf(fyEnd)

if (startMonth == 1) {
    context.fyLabel = "FY ${fyStart.year}"
} else {
    context.fyLabel = "FY ${fyStart.year}-${(fyEnd.year % 100).toString().padLeft(2, '0')}"
}

else.script:
def currencyNames = [INR:'Rupees', USD:'Dollars', GBP:'Pounds', EUR:'Euros',
                     AED:'Dirhams', AUD:'Dollars', CAD:'Dollars', JPY:'Yen',
                     SGD:'Dollars', SAR:'Riyals']
def subNames = [INR:'Paise', USD:'Cents', GBP:'Pence', EUR:'Cents',
                AED:'Fils', AUD:'Cents', CAD:'Cents', JPY:'Sen',
                SGD:'Cents', SAR:'Halalah']

def currName = currencyNames[currencyUomId] ?: currencyUomId
def subName = subNames[currencyUomId] ?: 'Cents'

def ones = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven',
            'Eight', 'Nine', 'Ten', 'Eleven', 'Twelve', 'Thirteen',
            'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen']
def tens = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty',
            'Sixty', 'Seventy', 'Eighty', 'Ninety']

def convertGroup = { int n ->
    if (n == 0) return ''
    def result = ''
    if (n >= 100) { result += ones[(int)(n / 100)] + ' Hundred '; n = n % 100 }
    if (n >= 20) { result += tens[(int)(n / 10)] + ' '; n = n % 10 }
    if (n > 0) { result += ones[n] + ' ' }
    return result.trim()
}

def wholeAmount = amount.toBigInteger().longValue()
def fractional = amount.remainder(BigDecimal.ONE).multiply(new BigDecimal(100)).intValue()

if (wholeAmount == 0) {
    context.amountInWords = "Zero ${currName}"
} else {
    def parts = []
    def scales = [[1000000000000L, 'Trillion'], [1000000000L, 'Billion'],
                  [1000000L, 'Million'], [1000L, 'Thousand']]
    def remaining = wholeAmount
    for (s in scales) {
        if (remaining >= s[0]) {
            parts.add(convertGroup((int)(remaining / s[0])) + ' ' + s[1])
            remaining = remaining % s[0]
        }
    }
    if (remaining > 0) parts.add(convertGroup((int) remaining))
    context.amountInWords = parts.join(' ') + ' ' + currName
}

if (fractional > 0) {
    context.amountInWords += ' and ' + convertGroup(fractional) + ' ' + subName
}

context.amountInWords += ' Only'
